import sys
from collections import defaultdict, deque

def findOrder(dict_words, N, K):
    graph = defaultdict(list)
    in_degree = {chr(ord('a') + i): 0 for i in range(K)}

    for i in range(len(dict_words) - 1):
        w1, w2 = dict_words[i], dict_words[i+1]
        min_len = min(len(w1), len(w2))
        for j in range(min_len):
            if w1[j] != w2[j]:
                graph[w1[j]].append(w2[j])
                break

    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = deque()
    for char in in_degree:
        if in_degree[char] == 0:
            queue.append(char)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) < K:
        return ""

    return "".join(result)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        K = int(next(iterator))
        dict_words = []
        for _ in range(N):
            dict_words.append(next(iterator))
    except StopIteration:
        return

    result = findOrder(dict_words, N, K)
    print(result)

if __name__ == "__main__":
    main()
